1	import { PrismaClient } from "@prisma/client";
2	import bcrypt from "bcryptjs";
3	import { randomBytes } from "node:crypto";
4	import { writeFileSync } from "node:fs";
5	
6	const db = new PrismaClient();
7	
8	// Prices include a dedicated IPv4 (the $3/mo IP cost is folded into the plan
9	// price and `dedicated_ip_price_cents` defaults to 0), so "dedicated IP included"
10	// marketing is accurate and customers see one honest number.
11	const plans = [
12	  { slug: "nano",     name: "Nano",     cpuCores: 1, ramMB: 1024,  diskGB: 15,  bandwidthTB: 1, priceCents: 649,  sortOrder: 1 },
13	  { slug: "starter",  name: "Starter",  cpuCores: 1, ramMB: 2048,  diskGB: 25,  bandwidthTB: 1, priceCents: 899,  sortOrder: 2 },
14	  { slug: "standard", name: "Standard", cpuCores: 2, ramMB: 4096,  diskGB: 50,  bandwidthTB: 2, priceCents: 1299, sortOrder: 3 },
15	  { slug: "pro",      name: "Pro",      cpuCores: 3, ramMB: 8192,  diskGB: 80,  bandwidthTB: 4, priceCents: 2099, sortOrder: 4 },
16	  { slug: "max",      name: "Max",      cpuCores: 4, ramMB: 16384, diskGB: 120, bandwidthTB: 8, priceCents: 3299, sortOrder: 5 },
17	];
18	
19	const osTemplates = [
20	  { slug: "ubuntu-24-04", name: "Ubuntu 24.04 LTS", vmid: 9000 },
21	  { slug: "debian-13",    name: "Debian 13",        vmid: 9001 },
22	];
23	
24	async function main() {
25	  for (const p of plans) {
26	    await db.plan.upsert({ where: { slug: p.slug }, update: p, create: p });
27	  }
28	  for (const t of osTemplates) {
29	    await db.osTemplate.upsert({ where: { slug: t.slug }, update: t, create: t });
30	  }
31	
32	  const adminEmail = "admin@nxeon.local";
33	  const existing = await db.user.findUnique({ where: { email: adminEmail } });
34	  if (!existing) {
35	    const password = randomBytes(12).toString("base64url");
36	    await db.user.create({
37	      data: {
38	        email: adminEmail,
39	        name: "Nxeon Admin",
40	        role: "ADMIN",
41	        passwordHash: await bcrypt.hash(password, 12),
42	      },
43	    });
44	    const credFile = process.env.NXEON_CRED_FILE ?? "/root/nxeon-credentials.txt";
45	    writeFileSync(credFile, `Nxeon admin login\nURL: ${process.env.APP_URL ?? "http://51.79.162.96/"}\nEmail: ${adminEmail}\nPassword: ${password}\n`, { mode: 0o600 });
46	    console.log(`Admin created: ${adminEmail} (password written to /root/nxeon-credentials.txt)`);
47	  }
48	  console.log("Seed complete");
49	}
50	
51	main().finally(() => db.$disconnect());
