1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import {
4	  STALE_INTERVAL_MULTIPLE,
5	  backupScheduleHealth,
6	  freshBackupProof,
7	  humanBytes,
8	  isAutoBackupDue,
9	} from "../lib/backup-verify.ts";
10	
11	/**
12	 * The backup verification gate — the pure decision logic that stands between
13	 * "the vzdump task returned" and telling a customer they have a restore point.
14	 *
15	 * Every case here is the 2026-07-26 rehearsal finding H4 or one of its edges.
16	 * Deterministic: no Prisma, no Proxmox, no clock — every entry point takes `now`.
17	 */
18	
19	const H = 60 * 60_000;
20	const T0 = Date.parse("2026-07-26T04:00:00.000Z");
21	
22	/* ------------------------------------------------------------------ *
23	 * 1. "Last automatic backup: today" while nothing was ever written
24	 *    Incident H4: `lastAutoBackup` was stamped by the SWEEP when the job row was
25	 *    ENQUEUED, and written nowhere else. backupCreate gated only the vzdump
26	 *    task's exit status — it never checked that an archive existed. So vzdump
27	 *    could fail every night for a month behind a fresh nightly timestamp, the
28	 *    schedule read as satisfied, and the customer found out at restore time.
29	 *    Proof is now a volid that was not there before the run and is not empty.
30	 * ------------------------------------------------------------------ */
31	
32	const EXISTING = [
33	  { volid: "backup:backup/vzdump-qemu-102-2026_07_25-04_00_11.vma.zst", vmid: 102, size: 8_500_000_000 },
34	];
35	
36	test("a task that returned but wrote no archive is NOT a backup", () => {
37	  // The exact H4 shape: vzdump "succeeded", storage is unchanged.
38	  const p = freshBackupProof({ vmid: 102, before: EXISTING, after: EXISTING });
39	  assert.equal(p.proven, false);
40	  assert.match(p.reason, /no new archive for VMID 102/);
41	  assert.match(p.reason, /there is no restore point from this run/);
42	  assert.match(p.reason, /pvesm list backup --vmid 102/, "every refusal carries a command the operator can run");
43	});
44	
45	test("a new, non-empty archive is proof — and the volid is reported, not inferred", () => {
46	  const after = [
47	    ...EXISTING,
48	    { volid: "backup:backup/vzdump-qemu-102-2026_07_26-04_00_09.vma.zst", vmid: 102, size: 8_600_000_000 },
49	  ];
50	  const p = freshBackupProof({ vmid: 102, before: EXISTING, after });
51	  assert.equal(p.proven, true);
52	  assert.ok(p.proven && p.volid.endsWith("2026_07_26-04_00_09.vma.zst"));
53	  assert.ok(p.proven && p.sizeBytes === 8_600_000_000);
54	});
55	
56	test("a 0-byte archive is refused — an empty file would only fail at restore time", () => {
57	  const after = [...EXISTING, { volid: "backup:backup/vzdump-qemu-102-2026_07_26.vma.zst", vmid: 102, size: 0 }];
58	  const p = freshBackupProof({ vmid: 102, before: EXISTING, after });
59	  assert.equal(p.proven, false);
60	  assert.match(p.reason, /0 bytes/);
61	  assert.match(p.reason, /would fail at restore time/);
62	});
63	
64	test("an archive with no reported size is refused rather than assumed good", () => {
65	  // Absence of evidence is not evidence. The house rule is: prefer refusing.
66	  const after = [...EXISTING, { volid: "backup:backup/vzdump-qemu-102-new.vma.zst", vmid: 102 }];
67	  const p = freshBackupProof({ vmid: 102, before: EXISTING, after });
68	  assert.equal(p.proven, false);
69	  assert.match(p.reason, /reported no size/);
70	  assert.match(p.reason, /Not recording a backup we cannot prove/);
71	});
72	
73	test("another VM's fresh archive is never mistaken for ours", () => {
74	  // The platform's own nightly run writes archives for every VMID on the box.
75	  const after = [
76	    ...EXISTING,
77	    { volid: "backup:backup/vzdump-qemu-103-2026_07_26-04_00_09.vma.zst", vmid: 103, size: 9_000_000_000 },
78	  ];
79	  assert.equal(freshBackupProof({ vmid: 102, before: EXISTING, after }).proven, false);
80	});
81	
82	test("membership, not timestamps — a pre-existing archive can never re-prove itself", () => {
83	  // Deliberately chosen over a ctime window: ctime comes off the hypervisor and
84	  // the window would come off the worker's clock, so skew between the two would
85	  // turn the proof back into a guess. Here the only archive is 24h old and its
86	  // ctime is in the future relative to nothing we consult.
87	  const stale = [{ volid: "v1", vmid: 7, size: 1234, ctime: 4_102_444_800 }];
88	  assert.equal(freshBackupProof({ vmid: 7, before: stale, after: stale }).proven, false);
89	});
90	
91	test("a truncated stub beside a good archive does not sink the good one", () => {
92	  const after = [
93	    { volid: "good", vmid: 9, size: 5_000_000 },
94	    { volid: "stub", vmid: 9, size: 0 },
95	  ];
96	  const p = freshBackupProof({ vmid: 9, before: [], after });
97	  assert.equal(p.proven, true);
98	  assert.ok(p.proven && p.volid === "good");
99	});
100	
101	/* ------------------------------------------------------------------ *
102	 * 2. The schedule anchors on the ATTEMPT, never on the success
103	 *    Dropping the enqueue-time stamp is only half the fix. Anchoring the next
104	 *    run on the last SUCCESS looks more correct and is a trap: a server whose
105	 *    backups always fail has no success to anchor to, so it is "due" on every
106	 *    15-minute sweep pass forever — hammering a sick VM and burying the rest of
107	 *    the fleet's queue behind it on a strictly serial worker.
108	 * ------------------------------------------------------------------ */
109	
110	test("a server that has never been attempted is due immediately", () => {
111	  assert.equal(isAutoBackupDue({ now: T0, intervalHours: 24, lastAttemptAt: null }), true);
112	});
113	
114	test("the cadence is measured from the attempt, even when the attempt failed", () => {
115	  const attempted = new Date(T0);
116	  assert.equal(isAutoBackupDue({ now: T0 + 23 * H, intervalHours: 24, lastAttemptAt: attempted }), false);
117	  assert.equal(isAutoBackupDue({ now: T0 + 24 * H, intervalHours: 24, lastAttemptAt: attempted }), true);
118	});
119	
120	test("a schedule with no interval is never due, and cannot divide by zero into a loop", () => {
121	  assert.equal(isAutoBackupDue({ now: T0, intervalHours: null, lastAttemptAt: null }), false);
122	  assert.equal(isAutoBackupDue({ now: T0, intervalHours: 0, lastAttemptAt: null }), false);
123	  assert.equal(isAutoBackupDue({ now: T0, intervalHours: -5, lastAttemptAt: null }), false);
124	});
125	
126	/* ------------------------------------------------------------------ *
127	 * 3. Absence is rendered, not hidden
128	 *    The panel used to print "Last automatic backup: <date>" or, when the column
129	 *    was null, "none yet — the first one runs on the next sweep" — which reads
130	 *    identically on a brand-new server and on one whose backups have failed
131	 *    thirty nights running. These are different facts and the customer needs to
132	 *    be able to tell them apart.
133	 * ------------------------------------------------------------------ */
134	
135	const base = { now: T0, autoBackup: true, intervalHours: 24 };
136	
137	test("never attempted reads as pending, and promises nothing", () => {
138	  const h = backupScheduleHealth({ ...base, lastVerifiedAt: null, lastAttempt: null });
139	  assert.equal(h.state, "pending");
140	  assert.match(h.detail, /No automatic backup has run yet/);
141	});
142	
143	test("attempted but never verified is called out — this is the H4 customer", () => {
144	  const h = backupScheduleHealth({
145	    ...base,
146	    lastVerifiedAt: null,
147	    lastAttempt: { at: new Date(T0 - 30 * 24 * H), status: "DONE" },
148	  });
149	  assert.equal(h.state, "never");
150	  assert.match(h.detail, /none has been verified to exist in storage/);
151	  assert.match(h.detail, /Do not rely on having a restore point/);
152	  assert.ok(!/none yet/.test(h.detail), "must not read like a fresh server");
153	});
154	
155	test("a failed last attempt outranks everything else and says so plainly", () => {
156	  const h = backupScheduleHealth({
157	    ...base,
158	    lastVerifiedAt: new Date(T0 - 12 * H),
159	    lastAttempt: { at: new Date(T0 - 1 * H), status: "FAILED" },
160	  });
161	  assert.equal(h.state, "failing");
162	  assert.match(h.detail, /FAILED/);
163	  assert.match(h.detail, /most recent backup we can prove exists is from 2026-07-25 16:00 UTC/);
164	  assert.match(h.detail, /do not assume tonight's run will fix it/i);
165	});
166	
167	test("a verified backup inside the window is the only case that reads reassuring", () => {
168	  const h = backupScheduleHealth({
169	    ...base,
170	    lastVerifiedAt: new Date(T0 - 6 * H),
171	    lastAttempt: { at: new Date(T0 - 6 * H), status: "DONE" },
172	  });
173	  assert.equal(h.state, "ok");
174	  assert.match(h.detail, /Last verified backup: 2026-07-25 22:00 UTC/);
175	  assert.match(h.detail, /confirmed present in storage/);
176	});
177	
178	test("a verified-but-old backup goes stale rather than staying green", () => {
179	  // The silent-failure signature: proof exists, but it stopped being renewed.
180	  const justInside = backupScheduleHealth({
181	    ...base,
182	    lastVerifiedAt: new Date(T0 - STALE_INTERVAL_MULTIPLE * 24 * H),
183	    lastAttempt: null,
184	  });
185	  assert.equal(justInside.state, "ok", "exactly at the threshold is not yet stale");
186	
187	  const past = backupScheduleHealth({
188	    ...base,
189	    lastVerifiedAt: new Date(T0 - (STALE_INTERVAL_MULTIPLE * 24 + 1) * H),
190	    lastAttempt: null,
191	  });
192	  assert.equal(past.state, "stale");
193	  assert.match(past.detail, /not keeping up/);
194	  assert.match(past.detail, /unprotected/);
195	});
196	
197	test("a disabled schedule claims nothing at all", () => {
198	  assert.equal(backupScheduleHealth({ ...base, autoBackup: false, lastVerifiedAt: null, lastAttempt: null }).state, "off");
199	  assert.equal(
200	    backupScheduleHealth({ ...base, intervalHours: null, lastVerifiedAt: new Date(T0), lastAttempt: null }).state,
201	    "off",
202	    "enabled with no cadence is not a schedule",
203	  );
204	});
205	
206	test("humanBytes never renders a size that would misreport an archive", () => {
207	  assert.equal(humanBytes(0), "0 B");
208	  assert.equal(humanBytes(1024), "1.0 KB");
209	  assert.equal(humanBytes(8_600_000_000), "8.0 GB");
210	  assert.equal(humanBytes(Number.NaN), "unknown size");
211	  assert.equal(humanBytes(-1), "unknown size");
212	});
