1	/**
2	 * Shared source-reading helpers for the structural tripwire suites.
3	 *
4	 * NOT named `*.test.ts` on purpose: `npm test` globs `test/*.test.ts`, so this
5	 * module is imported, never executed as a suite. It used to live inside
6	 * customer-actions-guards.test.ts and be imported from there, which made every
7	 * assertion in that file run a second time under the importing suite's name.
8	 */
9	export function stripComments(src: string): string {
10	  let out = "";
11	  let i = 0;
12	  const n = src.length;
13	  let quote: string | null = null;
14	  /** Last non-whitespace character emitted — decides `/` = regex vs. division. */
15	  let prev = "";
16	
17	  /** Positions where a `/` begins a regex literal rather than a division. */
18	  const REGEX_PRECEDERS = new Set(["", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n"]);
19	  const REGEX_KEYWORDS = /\b(return|typeof|case|in|of|delete|void|instanceof|new|do|else|yield|await)\s*$/;
20	
21	  while (i < n) {
22	    const c = src[i];
23	    const next = src[i + 1];
24	
25	    if (quote) {
26	      out += c;
27	      if (c === "\\") {
28	        // Escape: copy the escaped character too, so `\"` never closes a string.
29	        if (i + 1 < n) out += src[i + 1];
30	        i += 2;
31	        continue;
32	      }
33	      if (c === quote) quote = null;
34	      i++;
35	      continue;
36	    }
37	
38	    if (c === '"' || c === "'" || c === "`") {
39	      quote = c;
40	      out += c;
41	      prev = c;
42	      i++;
43	      continue;
44	    }
45	
46	    // `//` and `/*` are ALWAYS comments in valid JS — a regex literal cannot
47	    // begin with an unescaped `/` or a `*`. So comments win unconditionally, and
48	    // the regex branch below only ever sees a genuine literal.
49	    if (c === "/" && next === "/") {
50	      while (i < n && src[i] !== "\n") i++;
51	      out += " ";
52	      continue;
53	    }
54	    if (c === "/" && next === "*") {
55	      i += 2;
56	      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
57	      i += 2;
58	      out += " ";
59	      continue;
60	    }
61	
62	    // A regex literal must be consumed whole, or its escaped slashes (`\/\/` in
63	    // `/^https?:\/\//`) look like the start of a comment and eat the rest of the
64	    // line — silently deleting real code from everything asserted below.
65	    if (c === "/" && (REGEX_PRECEDERS.has(prev) || REGEX_KEYWORDS.test(out))) {
66	      out += c;
67	      i++;
68	      let inClass = false;
69	      for (; i < n; i++) {
70	        const r = src[i];
71	        out += r;
72	        if (r === "\\") {
73	          if (i + 1 < n) out += src[i + 1];
74	          i++;
75	          continue;
76	        }
77	        if (r === "[") inClass = true;
78	        else if (r === "]") inClass = false;
79	        else if (r === "/" && !inClass) {
80	          i++;
81	          break;
82	        } else if (r === "\n") {
83	          // Not a regex after all (unterminated) — stop rather than run away.
84	          i++;
85	          break;
86	        }
87	      }
88	      prev = "/";
89	      continue;
90	    }
91	
92	    out += c;
93	    if (!/\s/.test(c) || c === "\n") prev = c;
94	    i++;
95	  }
96	  return out;
97	}
