import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  TARGET_ENV_VAR,
  databaseNameFromUrl,
  decideDbTarget,
} from "../scripts/db-target-guard.ts";

/**
 * The guard that stands between a writing script and the wrong database.
 *
 * Incident, 2026-07-26: `prisma/seed.ts` was run from a scratch tree whose
 * `node_modules` was symlinked to /opt/nxeon/node_modules. Prisma's dotenv loader
 * walks up from the client's REAL location, so it loaded /opt/nxeon/.env and the
 * seed connected to PRODUCTION while every human signal said "scratch". It was an
 * idempotent upsert and did no damage — luck, not a control.
 *
 * The decision function is pure, so every case below runs with no database.
 */

const S = "prisma/seed.ts";

/* ------------------------------------------------------------------ *
 * 1. Reading the target out of a connection string
 * ------------------------------------------------------------------ */

test("the database name is read from the URL path, not guessed", () => {
  assert.equal(databaseNameFromUrl("postgresql://u:p@localhost:5432/nxeon"), "nxeon");
  assert.equal(databaseNameFromUrl("postgres://u:p@localhost:5432/nxeon_staging"), "nxeon_staging");
  assert.equal(
    databaseNameFromUrl("postgresql://u:p@localhost:5432/nxeon?schema=public&sslmode=require"),
    "nxeon",
    "query parameters are not part of the database name",
  );
});

test("a URL we cannot read yields no name, so nothing can be confirmed against it", () => {
  // Absence of evidence is not evidence: an unreadable target must refuse, never
  // fall through to a default.
  assert.equal(databaseNameFromUrl(undefined), null);
  assert.equal(databaseNameFromUrl(""), null);
  assert.equal(databaseNameFromUrl("not a url"), null);
  assert.equal(databaseNameFromUrl("mysql://u:p@localhost/nxeon"), null, "wrong engine");
  assert.equal(databaseNameFromUrl("postgresql://u:p@localhost:5432/"), null, "no database named");
  assert.equal(databaseNameFromUrl("postgresql://u:p@localhost:5432"), null);
});

test("a percent-encoded database name is decoded, and a malformed escape refuses", () => {
  assert.equal(databaseNameFromUrl("postgresql://u:p@h:5432/my%20db"), "my db");
  assert.equal(databaseNameFromUrl("postgresql://u:p@h:5432/bad%ZZ"), null);
});

/* ------------------------------------------------------------------ *
 * 2. The refusals — each one is a way the incident could recur
 * ------------------------------------------------------------------ */

test("an undeclared target is refused, and the refusal NAMES the database it would have hit", () => {
  // The whole failure was that the resolved target was invisible. Printing it is
  // the point: this is the line that makes a wrong .env obvious.
  const d = decideDbTarget({
    databaseUrl: "postgresql://nxeon:pw@localhost:5432/nxeon",
    declared: undefined,
    script: S,
  });
  assert.equal(d.allowed, false);
  assert.equal(d.database, "nxeon");
  assert.ok(!d.allowed && /Nothing was written/.test(d.message));
  assert.ok(!d.allowed && /resolves to the database: nxeon/.test(d.message));
  assert.ok(
    !d.allowed && d.message.includes(`${TARGET_ENV_VAR}=nxeon`),
    "the refusal carries the exact command that would proceed",
  );
});

test("declaring a DIFFERENT database is refused — the exact shape of the incident", () => {
  // Operator believes they are seeding a scratch DB; the environment silently
  // resolved to production. A blanket --force would have said yes here, because
  // the operator DID want to seed. Naming the target is what catches it.
  const d = decideDbTarget({
    databaseUrl: "postgresql://nxeon:pw@localhost:5432/nxeon",
    declared: "nxeon_scratch",
    script: S,
  });
  assert.equal(d.allowed, false);
  assert.ok(!d.allowed && /does not match what you asked for/.test(d.message));
  assert.ok(!d.allowed && /nxeon_scratch/.test(d.message), "shows what was asked for");
  assert.ok(!d.allowed && /resolved to\): nxeon/.test(d.message), "shows what it resolved to");
  assert.ok(!d.allowed && /symlinked node_modules/.test(d.message), "names the likely cause");
});

test("a missing DATABASE_URL is refused rather than defaulted", () => {
  const d = decideDbTarget({ databaseUrl: undefined, declared: "nxeon", script: S });
  assert.equal(d.allowed, false);
  assert.equal(d.database, null);
  assert.ok(!d.allowed && /DATABASE_URL is not set/.test(d.message));
});

test("an unparseable DATABASE_URL is refused even when a target is declared", () => {
  // Declaring "nxeon" must not license writing to something we cannot identify.
  const d = decideDbTarget({ databaseUrl: "postgresql://:::/", declared: "nxeon", script: S });
  assert.equal(d.allowed, false);
  assert.ok(!d.allowed && /does not name a PostgreSQL database/.test(d.message));
});

test("whitespace and empty strings are not a declaration", () => {
  for (const declared of ["", "   ", "\t\n"]) {
    const d = decideDbTarget({
      databaseUrl: "postgresql://u:p@h:5432/nxeon",
      declared,
      script: S,
    });
    assert.equal(d.allowed, false, `${JSON.stringify(declared)} must not count as declared`);
    assert.ok(!d.allowed && new RegExp(`${TARGET_ENV_VAR} is not set`).test(d.message));
  }
});

test("the match is exact — a prefix of the real database name is not close enough", () => {
  // "nxeon" vs "nxeon_staging" is the single most likely typo on this host, and
  // it is the difference between staging and every paying customer's record.
  for (const declared of ["nxeon_stagin", "nxeon_staging2", "NXEON_STAGING", "nxeon"]) {
    const d = decideDbTarget({
      databaseUrl: "postgresql://u:p@h:5432/nxeon_staging",
      declared,
      script: S,
    });
    assert.equal(d.allowed, false, `${declared} must not match nxeon_staging`);
  }
});

/* ------------------------------------------------------------------ *
 * 3. The one case that proceeds
 * ------------------------------------------------------------------ */

test("an explicit, matching declaration is allowed", () => {
  const d = decideDbTarget({
    databaseUrl: "postgresql://u:p@h:5432/nxeon_staging?schema=public",
    declared: "nxeon_staging",
    script: S,
  });
  assert.equal(d.allowed, true);
  assert.ok(d.allowed && d.database === "nxeon_staging");
});

test("surrounding whitespace in the declaration is tolerated, not the value", () => {
  const d = decideDbTarget({
    databaseUrl: "postgresql://u:p@h:5432/nxeon_staging",
    declared: "  nxeon_staging \n",
    script: S,
  });
  assert.equal(d.allowed, true);
});

/* ------------------------------------------------------------------ *
 * 4. Structural tripwire: the seed must actually be wired to the guard
 *    A guard nothing calls is decoration. This asserts the wiring, and that the
 *    check happens before a client is constructed.
 * ------------------------------------------------------------------ */

test("prisma/seed.ts calls the guard, and does so before constructing PrismaClient", () => {
  const src = readFileSync(new URL("../prisma/seed.ts", import.meta.url), "utf8");
  assert.ok(/assertDbTarget\(/.test(src), "seed.ts must call assertDbTarget()");

  const guardAt = src.indexOf("assertDbTarget(\"prisma/seed.ts\")");
  const clientAt = src.indexOf("new PrismaClient(");
  assert.ok(guardAt > 0, "the guard call must be present at top level");
  assert.ok(clientAt > 0, "sanity: the seed still constructs a client");
  assert.ok(
    guardAt < clientAt,
    "the target must be confirmed BEFORE a client exists, so a wrong target never opens a connection",
  );
});

test("prisma/seed.ts reports a failure instead of exiting clean", () => {
  // deploy-staging.sh runs `npm run db:seed ... || true`, so a seed that throws
  // into an unhandled rejection is indistinguishable from a seed that worked.
  const src = readFileSync(new URL("../prisma/seed.ts", import.meta.url), "utf8");
  assert.ok(/\.catch\(/.test(src), "main() must have a .catch");
  assert.ok(/process\.exit\(1\)/.test(src), "a failed seed must exit non-zero");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, utimesSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

/**
 * Per-guest backup coverage — scripts/guest-backup-coverage.sh.
 *
 * The check this replaces was `compgen -G vzdump-qemu-<vmid>-*`: does a file with
 * this vmid in its name exist. That answers "has this NUMBER ever been backed up",
 * which is not "is this GUEST protected", and the two come apart in two ways that
 * both reported healthy:
 *
 *   STALE   — a guest whose backups failed every night for a month still has its
 *             first archive on disk, so the glob matched.
 *   FOREIGN — Proxmox /cluster/nextid recycles the LOWEST free vmid to the next
 *             customer while archives named after that vmid persist, so a brand
 *             new customer inherited the previous tenant's "coverage" and reported
 *             protected having never been backed up.
 *
 * Driven against fixture directories, so every case runs with no Proxmox, no real
 * archives, and a pinned clock.
 */

const SCRIPT = new URL("../scripts/guest-backup-coverage.sh", import.meta.url).pathname;

/** Pinned "now" so ages are exact rather than dependent on wall-clock. */
const NOW = 1_800_000_000; // epoch seconds
const HOUR = 3600;

type Guest = {
  vmid: number;
  /** Archive mtimes, epoch seconds. Empty/omitted = no archive at all. */
  archives?: number[];
  /** Guest creation epoch written into the `meta:` line. Omit for no meta line. */
  created?: number;
};

function run(guests: Guest[], opts: { maxAgeHours?: number } = {}) {
  const root = mkdtempSync(join(tmpdir(), "nxeon-coverage-"));
  const platform = join(root, "platform");
  const confs = join(root, "qemu-server");
  mkdirSync(platform);
  mkdirSync(confs);

  for (const g of guests) {
    for (const [i, ts] of (g.archives ?? []).entries()) {
      // Names carry a distinct index so "which archive was chosen" is assertable.
      const f = join(platform, `vzdump-qemu-${g.vmid}-slot${i}.vma.zst`);
      writeFileSync(f, "x");
      utimesSync(f, ts, ts);
    }
    const meta = g.created === undefined ? "" : `meta: creation-qemu=11.0.2,ctime=${g.created}\n`;
    writeFileSync(join(confs, `${g.vmid}.conf`), `${meta}name: guest-${g.vmid}\ncores: 2\n`);
  }

  try {
    const out = execFileSync("bash", [SCRIPT], {
      encoding: "utf8",
      env: {
        ...process.env,
        NXEON_PLATFORM_BACKUP_DIR: platform,
        NXEON_PVE_CONF_DIR: confs,
        NXEON_BACKUP_MAX_AGE_HOURS: String(opts.maxAgeHours ?? 48),
        NXEON_COVERAGE_VMIDS: guests.map((g) => g.vmid).join(" "),
        NXEON_COVERAGE_NOW: String(NOW),
      },
    });
    const verdicts = new Map<number, { verdict: string; detail: string }>();
    for (const line of out.trim().split("\n").filter(Boolean)) {
      const [vmid, verdict, ...rest] = line.split(" ");
      verdicts.set(Number(vmid), { verdict, detail: rest.join(" ") });
    }
    return verdicts;
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}

/* ------------------------------------------------------------------ *
 * 1. The healthy case
 * ------------------------------------------------------------------ */

test("a fresh archive that postdates the guest's creation is coverage", () => {
  const v = run([{ vmid: 100, created: NOW - 30 * 24 * HOUR, archives: [NOW - 2 * HOUR] }]);
  assert.equal(v.get(100)?.verdict, "OK");
});

/* ------------------------------------------------------------------ *
 * 2. Nothing at all
 * ------------------------------------------------------------------ */

test("a guest with no archive is MISSING, not silently skipped", () => {
  const v = run([{ vmid: 104, created: NOW - 10 * HOUR }]);
  assert.equal(v.get(104)?.verdict, "MISSING");
});

/* ------------------------------------------------------------------ *
 * 3. STALE — the month-of-failures case the old glob could not see
 * ------------------------------------------------------------------ */

test("an archive older than the freshness bound is STALE even though the file exists", () => {
  // This is precisely what `compgen -G` reported as covered.
  const v = run([{ vmid: 101, created: NOW - 60 * 24 * HOUR, archives: [NOW - 30 * 24 * HOUR] }]);
  assert.equal(v.get(101)?.verdict, "STALE");
  assert.match(v.get(101)!.detail, /720h old/);
});

test("the freshness boundary is exact at the bound", () => {
  const created = NOW - 90 * 24 * HOUR;
  const justInside = run([{ vmid: 1, created, archives: [NOW - 47 * HOUR] }]);
  assert.equal(justInside.get(1)?.verdict, "OK", "47h with a 48h bound is still covered");

  const atBound = run([{ vmid: 1, created, archives: [NOW - 48 * HOUR] }]);
  assert.equal(atBound.get(1)?.verdict, "STALE", "48h with a 48h bound is stale");
});

test("one healthy guest cannot vouch for a rotten one", () => {
  // The aggregate "newest archive on the platform" check is green here, because
  // guest 100 backed up an hour ago. Per-guest is the only thing that sees 102.
  const v = run([
    { vmid: 100, created: NOW - 40 * 24 * HOUR, archives: [NOW - 1 * HOUR] },
    { vmid: 102, created: NOW - 40 * 24 * HOUR, archives: [NOW - 20 * 24 * HOUR] },
  ]);
  assert.equal(v.get(100)?.verdict, "OK");
  assert.equal(v.get(102)?.verdict, "STALE");
});

/* ------------------------------------------------------------------ *
 * 4. FOREIGN — the recycled vmid
 * ------------------------------------------------------------------ */

test("a recycled vmid does not inherit the previous tenant's coverage", () => {
  // The shape: old tenant on vmid 102 was destroyed; /cluster/nextid handed 102 to
  // a new customer an hour ago; the old archives are still on disk and are FRESH,
  // so both the glob AND a pure freshness check call this covered.
  const v = run([{ vmid: 102, created: NOW - 1 * HOUR, archives: [NOW - 3 * HOUR] }]);
  assert.equal(v.get(102)?.verdict, "FOREIGN");
  assert.match(v.get(102)!.detail, /predates guest creation/);
  assert.match(v.get(102)!.detail, /previous tenant/);
});

test("FOREIGN outranks STALE — 'somebody else's archive' is not 'an old archive'", () => {
  // Reporting this as merely stale would imply the next nightly run fixes it. It
  // does not: the archive that is there is not this guest's data.
  const v = run([{ vmid: 103, created: NOW - 5 * HOUR, archives: [NOW - 90 * 24 * HOUR] }]);
  assert.equal(v.get(103)?.verdict, "FOREIGN");
});

test("an archive taken one second after creation is this guest's, not the last tenant's", () => {
  const v = run([{ vmid: 105, created: NOW - 10 * HOUR, archives: [NOW - 10 * HOUR + 1] }]);
  assert.equal(v.get(105)?.verdict, "OK");
});

/* ------------------------------------------------------------------ *
 * 5. Degrading safely when Proxmox tells us nothing
 * ------------------------------------------------------------------ */

test("a guest with no meta/ctime line degrades to freshness, never to FOREIGN", () => {
  // Guests created before PVE wrote `meta:` have no creation date. Inventing one
  // would manufacture false FOREIGN verdicts on the platform's oldest guests.
  const fresh = run([{ vmid: 106, archives: [NOW - 2 * HOUR] }]);
  assert.equal(fresh.get(106)?.verdict, "OK");

  const old = run([{ vmid: 106, archives: [NOW - 50 * HOUR] }]);
  assert.equal(old.get(106)?.verdict, "STALE");
});

test("a missing config file is not fatal and does not fabricate a verdict", () => {
  const v = run([{ vmid: 107, created: NOW - 5 * HOUR, archives: [NOW - 1 * HOUR] }]);
  assert.equal(v.get(107)?.verdict, "OK");
});

/* ------------------------------------------------------------------ *
 * 6. Picking the right archive
 * ------------------------------------------------------------------ */

test("the NEWEST archive decides, not whichever the glob happened to list first", () => {
  // keep-last=3 leaves several archives per vmid; an old one must not sink a guest
  // that backed up last night, and a fresh one must not rescue a FOREIGN set.
  const v = run([
    { vmid: 108, created: NOW - 40 * 24 * HOUR, archives: [NOW - 30 * 24 * HOUR, NOW - 1 * HOUR, NOW - 15 * 24 * HOUR] },
  ]);
  assert.equal(v.get(108)?.verdict, "OK");
  assert.match(v.get(108)!.detail, /1h old/);
});

test("every guest gets exactly one verdict", () => {
  const guests = [
    { vmid: 100, created: NOW - 5 * HOUR, archives: [NOW - 1 * HOUR] },
    { vmid: 101, created: NOW - 5 * HOUR },
    { vmid: 102, created: NOW - 1 * HOUR, archives: [NOW - 3 * HOUR] },
  ];
  const v = run(guests);
  assert.equal(v.size, 3);
  assert.deepEqual(
    [v.get(100)?.verdict, v.get(101)?.verdict, v.get(102)?.verdict],
    ["OK", "MISSING", "FOREIGN"],
  );
});

