import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

/**
 * scripts/firewall-reachability.sh — does the ruleset actually accept the ports
 * that must stay reachable?
 *
 * INCIDENT, 2026-07-26. `define ADMIN_PORTS` was narrowed from { 22, 8006 } to
 * { 8006 } so SSH would survive an admin-IP rotation. 22 was removed from the
 * restricted set but never added to the public `tcp dport { ... } accept` set,
 * because nothing ties the two hand-written lists together. The file passed
 * `nft -c` and applied cleanly, and with `policy drop` the input chain then had no
 * accept for tcp/22 at all. The live SSH session survived only on `ct state
 * established,related`; every new connection was dropped.
 *
 * `nft -c` checks SYNTAX. "This ruleset means deny" is not a syntax error. These
 * fixtures are nftables' own rendering, so the assertions are about what the
 * kernel would do, not about the source text.
 */

const SCRIPT = new URL("../scripts/firewall-reachability.sh", import.meta.url).pathname;

function check(rendered: string, ports: string) {
  const dir = mkdtempSync(join(tmpdir(), "nxeon-fw-"));
  const f = join(dir, "rendered.nft");
  writeFileSync(f, rendered);
  try {
    const out = execFileSync("bash", [SCRIPT, "--rendered", f, "--ports", ports], {
      encoding: "utf8",
    });
    return { code: 0, out };
  } catch (e: any) {
    return { code: e.status as number, out: (e.stdout ?? "") + (e.stderr ?? "") };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/** The ruleset as it stands today: 22 in the public accept set. */
const GOOD = `table inet nxeon_fw {
	chain input {
		type filter hook input priority filter; policy drop;
		ct state established,related accept
		ct state invalid drop
		iif "lo" accept
		iifname "vmbr1" drop
		ip saddr @nxeon_admin_v4 tcp dport 8006 counter packets 0 bytes 0 accept
		ip6 saddr @nxeon_admin_v6 tcp dport 8006 counter packets 0 bytes 0 accept
		tcp dport 8006 limit rate 10/minute burst 5 packets log prefix "nxeon-fw admin-deny "
		tcp dport 8006 counter packets 0 bytes 0 drop
		tcp dport { 22, 80, 443, 8080, 8443 } accept
	}
}`;

/** The 2026-07-26 ruleset: 22 out of ADMIN_PORTS, never added to the public set. */
const LOCKOUT = `table inet nxeon_fw {
	chain input {
		type filter hook input priority filter; policy drop;
		ct state established,related accept
		ct state invalid drop
		iif "lo" accept
		iifname "vmbr1" drop
		ip saddr @nxeon_admin_v4 tcp dport 8006 counter packets 0 bytes 0 accept
		tcp dport 8006 counter packets 0 bytes 0 drop
		tcp dport { 80, 443, 8080, 8443 } accept
	}
}`;

/* ------------------------------------------------------------------ *
 * 1. The incident itself
 * ------------------------------------------------------------------ */

test("the 2026-07-26 lockout ruleset is REFUSED — tcp/22 has no accept path", () => {
  const r = check(LOCKOUT, "22 80 443");
  assert.equal(r.code, 1, "must exit non-zero so --apply refuses");
  assert.match(r.out, /tcp\/22 has NO accept rule/);
  assert.match(r.out, /policy is drop/);
  assert.match(r.out, /80.*accepted|accepted.*80/s, "the ports that ARE fine are still reported fine");
});

test("the refusal explains why nobody noticed, and what to actually change", () => {
  // The failure was invisible precisely because open sessions kept working. A
  // message that does not say so invites "but I'm still connected, it's fine".
  const r = check(LOCKOUT, "22");
  assert.match(r.out, /Established/i);
  assert.match(r.out, /established,related/);
  assert.match(r.out, /does\s+NOT show up until someone reconnects/i);
  assert.match(r.out, /Change BOTH lists/);
});

test("the current ruleset passes", () => {
  const r = check(GOOD, "22 80 443");
  assert.equal(r.code, 0);
  assert.match(r.out, /tcp\/22 is accepted/);
});

/* ------------------------------------------------------------------ *
 * 2. Rule ORDER decides, because in nftables it does
 * ------------------------------------------------------------------ */

test("a drop ABOVE an accept wins — the accept is dead code", () => {
  const shadowed = `table inet nxeon_fw {
	chain input {
		type filter hook input priority filter; policy drop;
		tcp dport 22 counter packets 0 bytes 0 drop
		tcp dport { 22, 80, 443 } accept
	}
}`;
  const r = check(shadowed, "22");
  assert.equal(r.code, 1, "a shadowed accept must not read as reachable");
  assert.match(r.out, /tcp\/22 is explicitly DROPPED/);
});

test("an allowlisted accept ABOVE a blanket drop is admin-only, not unreachable", () => {
  // This is the live :8006 rule. Reporting it as broken would be a false alarm on
  // exactly the rule someone might then "fix" by reopening Proxmox to the internet.
  const r = check(GOOD, "8006");
  assert.equal(r.code, 0);
  assert.match(r.out, /tcp\/8006 is accepted ONLY from an allowlisted source/);
});

/* ------------------------------------------------------------------ *
 * 3. Reading the rules the way nft writes them
 * ------------------------------------------------------------------ */

test("both the set form and the single-port form are understood", () => {
  const single = `table inet nxeon_fw {
	chain input {
		type filter hook input priority filter; policy drop;
		tcp dport 22 accept
	}
}`;
  assert.equal(check(single, "22").code, 0);
});

test("a port range covers the ports inside it", () => {
  const ranged = `table inet nxeon_fw {
	chain input {
		type filter hook input priority filter; policy drop;
		tcp dport { 20-25, 443 } accept
	}
}`;
  assert.equal(check(ranged, "22 443").code, 0);
  assert.equal(check(ranged, "26").code, 1, "just outside the range is not accepted");
});

test("a policy-accept chain does not need an explicit rule", () => {
  const permissive = `table inet nxeon_fw {
	chain input {
		type filter hook input priority filter; policy accept;
		ct state invalid drop
	}
}`;
  assert.equal(check(permissive, "22 80").code, 0);
});

test("a counter/log rule that reaches no verdict does not decide the port", () => {
  // `tcp dport 8006 limit rate ... log prefix ...` has no accept/drop; nft falls
  // through to the next rule. Treating it as a verdict would misreport both ways.
  const r = check(GOOD, "8006");
  assert.equal(r.code, 0);
  assert.doesNotMatch(r.out, /8006 is explicitly DROPPED/);
});

/* ------------------------------------------------------------------ *
 * 4. Refusing to answer when it cannot
 * ------------------------------------------------------------------ */

test("a missing table or chain fails loudly rather than reporting all-clear", () => {
  const empty = `table inet other_table {
	chain input {
		type filter hook input priority filter; policy drop;
	}
}`;
  const r = check(empty, "22");
  assert.equal(r.code, 1);
  assert.match(r.out, /table nxeon_fw not present/);
});

test("the check covers every port it was asked about", () => {
  const r = check(GOOD, "22 80 443 8080 8443");
  assert.equal(r.code, 0);
  for (const p of [22, 80, 443, 8080, 8443]) {
    assert.match(r.out, new RegExp(`tcp/${p} is accepted`), `tcp/${p} must be reported`);
  }
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, chmodSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

/**
 * scripts/backup-vms.sh — the guest list it hands to vzdump.
 *
 * The array was assembled with `"${ARR[@]:-}"`. On an EMPTY array that does not
 * expand to nothing: `:-` substitutes its (empty) default and yields exactly ONE
 * empty-string element. So when `qm list` returned no guests — pve-cluster down,
 * `qm` missing, an output-format change — the array had length 1, the
 * `[ "${#VMIDS[@]}" -eq 0 ]` guard could never fire, and the script reached
 * `vzdump "" --dumpdir ...`: an empty vmid passed to the tool whose entire job is
 * to act on the guests you name it. The "host configuration backup only" branch
 * was unreachable code.
 *
 * Driven in DRY RUN with a stubbed `qm` on PATH, so no vzdump ever runs and no
 * archive, VM or storage is touched.
 */

const SCRIPT = new URL("../scripts/backup-vms.sh", import.meta.url).pathname;

/** Run backup-vms.sh in dry run with `qm list` stubbed to emit `qmOutput`. */
function run(qmOutput: string, env: Record<string, string> = {}) {
  const dir = mkdtempSync(join(tmpdir(), "nxeon-bvm-"));
  const bin = join(dir, "bin");
  mkdirSync(bin);
  // Stub `qm`. Only `qm list` is consulted; anything else exits 0 silently.
  const stub = join(bin, "qm");
  writeFileSync(stub, `#!/bin/sh\n[ "$1" = "list" ] || exit 0\ncat <<'EOF'\n${qmOutput}\nEOF\n`);
  chmodSync(stub, 0o755);
  // A vzdump stub that FAILS loudly if it is ever reached. Dry run must not call
  // it; if the guard regresses, this turns a silent misbehaviour into a red test.
  const vz = join(bin, "vzdump");
  writeFileSync(vz, `#!/bin/sh\necho "VZDUMP-WAS-CALLED args=[$*]" >&2\nexit 9\n`);
  chmodSync(vz, 0o755);

  try {
    const out = execFileSync("bash", [SCRIPT], {
      encoding: "utf8",
      env: {
        ...process.env,
        PATH: `${bin}:${process.env.PATH}`,
        NXEON_VM_BACKUP_DRYRUN: "1",
        NXEON_BACKUP_STATUS_DIR: join(dir, "status"),
        NXEON_PLATFORM_BACKUP_DIR: join(dir, "platform"),
        ...env,
      },
    });
    return { code: 0, out };
  } catch (e: any) {
    return { code: e.status as number, out: (e.stdout ?? "") + (e.stderr ?? "") };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const HEADER = "      VMID NAME                 STATUS     MEM(MB)    BOOTDISK(GB) PID";
const guest = (id: number, name: string) =>
  `       ${id} ${name.padEnd(20)} running    2048              25.00 1234`;

/* ------------------------------------------------------------------ *
 * 1. The bug: an empty guest list
 * ------------------------------------------------------------------ */

test("no guests means the host-config-only path, not vzdump with an empty vmid", () => {
  const r = run(HEADER);
  assert.equal(r.code, 0);
  assert.match(r.out, /no eligible guests found; host configuration backup only/);
  assert.doesNotMatch(r.out, /VZDUMP-WAS-CALLED/, "vzdump must never be reached");
  assert.doesNotMatch(r.out, /would run: vzdump/, "and must not even be planned");
});

test("a guest list of only templates, with templates disabled, is still empty", () => {
  // Templates are 9000+; excluding them can empty the list on a host that has
  // provisioned nothing yet — a brand-new box, which is exactly when nobody is
  // watching the backup logs.
  const r = run([HEADER, guest(9000, "tpl-ubuntu")].join("\n"), {
    NXEON_VM_BACKUP_INCLUDE_TEMPLATES: "0",
  });
  assert.equal(r.code, 0);
  assert.match(r.out, /no eligible guests found/);
  assert.doesNotMatch(r.out, /VZDUMP-WAS-CALLED/);
});

test("a completely unavailable `qm` is handled as no guests, not as an empty argument", () => {
  // `qm list 2>/dev/null` returning nothing is what a down pve-cluster looks like.
  const r = run("");
  assert.equal(r.code, 0);
  assert.match(r.out, /no eligible guests found/);
  assert.doesNotMatch(r.out, /VZDUMP-WAS-CALLED/);
});

/* ------------------------------------------------------------------ *
 * 2. The list is still correct when there ARE guests
 * ------------------------------------------------------------------ */

test("customer guests and templates are both included, in numeric order", () => {
  const r = run([HEADER, guest(104, "movieshack"), guest(100, "soulpilates"), guest(9001, "tpl-debian")].join("\n"));
  assert.equal(r.code, 0);
  assert.match(r.out, /eligible guests: 100 104 9001/);
  assert.match(r.out, /would run: vzdump 100 104 9001 /);
});

test("templates are excluded when asked, customers are never excluded", () => {
  const r = run([HEADER, guest(100, "soulpilates"), guest(9001, "tpl-debian")].join("\n"), {
    NXEON_VM_BACKUP_INCLUDE_TEMPLATES: "0",
  });
  assert.match(r.out, /eligible guests: 100$/m);
});

test("the planned vzdump command contains no empty arguments", () => {
  // The regression signature: `vzdump  --compress` (a doubled space where the
  // empty element was) or a stray `""`.
  const r = run([HEADER, guest(100, "soulpilates")].join("\n"));
  const line = r.out.split("\n").find((l) => l.includes("would run: vzdump"))!;
  assert.ok(line, "a dry-run plan line must be printed");
  const args = line.split("would run: vzdump ")[1];
  assert.doesNotMatch(args, /\s\s/, "no doubled whitespace from an empty element");
  assert.doesNotMatch(args, /""/, "no empty quoted argument");
  assert.match(args, /^100 --compress zstd/);
});

test("vmids outside [100, 9000) are not treated as guests", () => {
  // 99 and below are Proxmox's own reserved range; the awk filter must hold.
  const r = run([HEADER, guest(99, "reserved"), guest(100, "real")].join("\n"), {
    NXEON_VM_BACKUP_INCLUDE_TEMPLATES: "0",
  });
  assert.match(r.out, /eligible guests: 100$/m);
});
